// === Tab: mySketch.js ===
/** OPC START **/
OPC.slider('palette', ~~(Math.random()*6),0,5,1);
OPC.slider('number', ~~(Math.random()*9)+2,2,10,1);
OPC.slider('shape', ~~(Math.random()*4),0,3,1);
OPC.slider('mode', ~~(Math.random()*4),0,3,1);
OPC.slider('segments', ~~(Math.random()*4)+1,1,4,1);
OPC.slider('speed', ~~(Math.random()*4),0,3,1);
/** OPC END **/

let minHW, pt, t;
let padx = 0.05;
let PERIOD = 600;

function setup() {
	minHW = min([windowWidth, windowHeight]);
	pt = minHW / 1000;
  createCanvas(windowWidth, windowHeight);
	rectMode(CENTER)
}

function draw() {
	let t = ((frameCount-1)/PERIOD*(speed+0.1))%1;
	randomSeed(10);
	noiseSeed(10);
	blendMode(BLEND);
	colorMode(HSB);
	strokeWeight(pt*4);
	strokeJoin(MITER);
	strokeCap(PROJECT);
	bgColors = ["#000000","#FFFFFF","#759243","#0d2b52","#d1b0b3","#000000"];
	let bgColor = bgColors[palette];
	background(bgColor)

	dx = (1-2*padx)*width/(number);
	dys = [sqrt(3)/2,2/sqrt(3)/2,1,sqrt(3)/2];
	dy = dys[shape]*dx;
	as = [0,0,PI/4,0];

	let oddOffset = (shape==0||shape==3) ? 1 : 0;
	let dyMod = (shape==1) ? 1 : 0;
	let rs = [dx,2/sqrt(3)/2*2/sqrt(3)*dx,dx/2*1.414,dx*2/sqrt(3)/2];
	let sides = [0,3,4,6];

	let numy = ~~(height*(1-2*padx)/dy - 1*dyMod)
	let pady = (1 - dy*numy/height)/2;

	for (let j=0; j<numy; j++){
	for (let i=0; i<number; i++){ 
		let x = (i+.5+oddOffset*(j%2)/2)*dx + padx*width;
		let y = (j+.5)*dy + pady*height;

		if (!(oddOffset && j%2==1 && i==number-1)) {
			let odd = (shape==1) ? ((i%2==j%2) ? 1 : -1 ) : 0;
			let xm = (shape==1) ? - odd*dy*(2/sqrt(3) - sqrt(3)/2) : 0;
			let cnum = segments
			if (mode == 0) cnum=3;

			let alpha = 1;
			let hu = 360*random();

			noStroke();
			noFill();
			let close = true;
			if (mode==0) blendMode(DIFFERENCE)
			if (mode==1) alpha = 1/(pow(cnum,.5));
			if (mode==2) stroke(bgColor);
			if (mode==3) close = false;

			if (palette==0) col = color(0,0,100)
			if (palette==1) col = color(0,0,0)
			if (palette==2) col = color("#96bfe6")
			if (palette==3) col = color("#ff8c00")
			if (palette==4) col = color("#2d0060")
			if (palette==5) col = color(hu,100,100)			
			col.setAlpha(1);
			col.setAlpha(alpha);

			for (let c=0; c<cnum; c++){
				if (mode==0 && (palette==0 || palette==1)) col = color(120*c,100,100,alpha)
				if (mode==3) stroke(col)
				else fill(col)

				let dir = Math.sign(noise(i+j)-.5);
				push();
				translate(x,y)
				let sc = .95;
				if (mode==3) sc = 1*(1+c)/cnum;

				let start = .2+dir*t+c*.2+1 + noise(i+j*number+c);
				let delta = .4+.2*sq(sin(PI*(t+noise(j+i*numy+c))))
				if (shape==0) drawCircle(0,0,sc*dx,start,delta,close);
				else drawPolygon(xm,0,rs[shape]*sc,sides[shape],as[shape]+PI/2*odd,start,delta,close)
				if (mode==0 && c==cnum-1) {
					push()
					blendMode(BLEND)
					stroke(bgColor)
					strokeWeight(2)
					noFill()

					for (let ij=0; ij<2; ij++){
						if (shape==0) drawCircle(0,0,sc*dx,0,1,close);
						else drawPolygon(xm,0,rs[shape]*sc,sides[shape],as[shape]+PI/2*odd,0,1,close);
					}
					pop();
				}
				pop();
			}
		}
		}
	}

}

function drawCircle(x,y,r,start,delta,close){
	if (close) arc(x,y,r,r,start*TAU,(start+delta)*TAU,CHORD)
	else arc(x,y,r,r,start*TAU,(start+delta)*TAU)
}

function drawPolygon(x,y,r,sides,a,start,delta,close){
	beginShape()
	getVertex(start)
	let s0 = ~~(start*sides);
	let sf = ~~((start+delta)*sides)+1;
	for (let s=s0+1; s<sf; s++){
		let xv = x+r*sin(TAU/sides*s+a);
		let yv = y+r*cos(TAU/sides*s+a);
		vertex(xv,yv);
	}
	getVertex(start+delta);
	if (close) endShape(CLOSE);
	else endShape();
	function getVertex(sv){
		let s0 = ~~(sv*sides);
		let theta0 = TAU/sides*s0+a;
		let theta1 = TAU/sides*(s0+1)+a;
		let x0 = x+r*sin(theta0)
		let x1 = x+r*sin(theta1)
		let y0 = y+r*cos(theta0)
		let y1 = y+r*cos(theta1)
		let xv = map(sv*sides,s0,s0+1,x0,x1,true);
		let yv = map(sv*sides,s0,s0+1,y0,y1,true);
		return vertex(xv,yv)
	}
}

